"""Light reading layout (design system 'reading' theme) for articles and guides.
Injects <style id="udw-reading"> into the listed pages and adds DM Sans to their font link.
Charts, league tables and figure panels stay dark ('dark islands'). Idempotent."""
import re, pathlib

PAGES = ["articles/index.html", "uk-debt-interest/index.html", "who-owns-uk-debt/index.html",
         "uk-debt-vs-other-countries/index.html", "billionaires-leaving-uk/index.html", "help/index.html"]

CSS = """<style id="udw-reading">
/* Reading theme (warm white) — generated by _tools/reading.py. Dark islands keep the data look. */
:root{--bg:#f6f4f0;--panel:#fffdf9;--border:#d9d5cd;--text:#1c1c1c;--muted:#5c5c5c;--faint:#5c5c5c;--ice:#0e6f68;--gold:#a85a14;--amber:#a85a14;--teal:#0e6f68}
html,body{background:#f6f4f0;color:#1c1c1c;font-family:'DM Sans',system-ui,-apple-system,'Segoe UI',sans-serif}
body{display:flex;flex-direction:column;min-height:100vh}
a:focus-visible,button:focus-visible,summary:focus-visible{outline-color:#0e6f68}
/* dark islands: charts, figure panels, league tables */
.chart,.lt-wrap,.facts{--bg:#0a0a0a;--panel:#0d0d0d;--border:#272727;--text:#f5f2ee;--muted:#a8a8a8;--faint:#a8a8a8;--ice:#7fd8cf;--gold:#f0c040;--amber:#f4a261;--teal:#2ec4b6;color:#f5f2ee;font-family:'DM Mono',ui-monospace,Menlo,monospace}
.chart{background:#0d0d0d;border-color:#272727}
.chart a,.lt-wrap a,.facts a{color:#7fd8cf}
.chart-sub,.chart-src{color:#a8a8a8}

/* page title block */
.hero,.intro{background:transparent;border-bottom:0;text-align:left;max-width:776px;margin:0 auto;padding:56px 24px 8px;width:100%}
.hero::before,.intro::before{display:none}
.hero .eyebrow,.intro .eyebrow{font-family:'DM Mono',ui-monospace,Menlo,monospace;font-size:13px;letter-spacing:.2em;color:#b3262f;margin:0 0 16px}
.hero h1,.intro h1,h1{font-family:'DM Sans',system-ui,sans-serif;font-weight:700;font-size:44px;line-height:1.12;letter-spacing:-.015em;color:#111;max-width:none;margin:0 0 20px;text-align:left}
.hero h1 em,.intro h1 em{color:#b3262f}
.lede,.intro p{font-size:20px;line-height:1.55;color:#3d3d3d;max-width:none;margin:0 0 16px;text-align:left}
.intro p b{color:#111;font-weight:700}
.byline{font-family:'DM Mono',ui-monospace,Menlo,monospace;font-size:13px;color:#5c5c5c;letter-spacing:.04em;border-bottom:1px solid #d9d5cd;padding-bottom:20px;margin-top:4px}
.byline b{color:#1c1c1c;font-weight:500}
.updated{flex-wrap:wrap;gap:4px 9px;background:#fffdf9;border-color:#d9d5cd;color:#3d3d3d;font-family:'DM Mono',ui-monospace,Menlo,monospace}

/* article body */
article{max-width:776px;padding:32px 24px 20px}
article h2,.article h2,.prose h2,section > h2,.wrap h2{font-family:'DM Sans',sans-serif;font-weight:700;font-size:26px;line-height:1.25;letter-spacing:0;color:#111}
article h3,.steps h3{font-family:'DM Sans',sans-serif;font-size:20px;font-weight:700;color:#111;line-height:1.3}
article p,.article p,.steps p,.prose p,.article li,.steps li li,.prose li{font-size:18px;line-height:1.7;color:#262626}
article p strong,.article p b,.steps p b,.article li b,.steps li b,.prose b,.prose strong{color:#111;font-weight:700}
article p.stand{font-size:20px;line-height:1.6;color:#262626;border-left-color:#f04550}
article a,.article a,.steps a,.faq a,.callout a,.prose a,.fact a,.small-table a,.help-note a,.disclaimer a,.table-note a{color:#0e6f68;text-decoration:underline;text-underline-offset:2px}
article a:hover,.article a:hover,.prose a:hover,.faq a:hover{color:#0a4f4a}
article ul.list li{font-size:18px;color:#262626}
article ul.list li strong{color:#111;font-weight:700}
article ul.list li::before{color:#b3262f}
.keypoints{background:#fffdf9;border-color:#d9d5cd;border-left-color:#0e6f68}
.keypoints h2{color:#0e6f68}
.keypoints li{font-size:17px;color:#262626}
.keypoints li::before{color:#0e6f68}
.pull{background:#fffdf9;border-color:#d9d5cd;border-left:3px solid #f04550}
.pull .p-fig{font-family:'DM Mono',ui-monospace,Menlo,monospace;font-weight:500;color:#b3262f}
.pull .p-txt{font-size:16px;color:#3d3d3d}
.note{color:#5c5c5c !important;border-left-color:#d9d5cd !important;font-size:15px !important}
.qa{border-color:#d9d5cd}
.qa h3{font-family:'DM Sans',sans-serif;font-size:18px;font-weight:700;color:#111}
.qa p{font-size:17px;color:#3d3d3d}
.sources{border-color:#d9d5cd}
.sources h2{color:#111}
.sources li{font-size:14px;color:#5c5c5c}
.sources a{color:#0e6f68}
.related{background:#d9d5cd;border-color:#d9d5cd}
.related a,.hub-card{background:#fffdf9}
.related a:hover,.hub-card:hover{background:#fff}
.related .r-k,.hub-card .r-k,.read-next .rn-k{font-family:'DM Mono',ui-monospace,Menlo,monospace;color:#b3262f}
.related .r-t{font-size:17px;font-weight:700;color:#111}
.hub{background:#d9d5cd;border-color:#d9d5cd}
.hub-card h2{font-family:'DM Sans',sans-serif !important;font-weight:700;font-size:20px;color:#111}
.hub-card p{font-size:16px;color:#3d3d3d}
.read-next{background:#fffdf9;border-color:#d9d5cd;border-left-color:#f04550}
.read-next:hover{background:#fff}
.read-next .rn-t{font-family:'DM Sans',sans-serif;font-weight:700;color:#111}
.read-next .rn-d{font-size:16px;color:#3d3d3d}
.backlink a{font-family:'DM Mono',ui-monospace,Menlo,monospace;color:#0e6f68;border-color:#d9d5cd;background:#fffdf9}
.backlink a:hover{color:#0a4f4a;border-color:#0e6f68}
.dtable{font-size:15px}
.dtable caption{font-family:'DM Mono',ui-monospace,Menlo,monospace;color:#5c5c5c}
.dtable th{font-family:'DM Mono',ui-monospace,Menlo,monospace;color:#5c5c5c;border-color:#d9d5cd}
.dtable td{color:#262626;border-color:#e6e2da}
.dtable td.num{font-family:'DM Mono',ui-monospace,Menlo,monospace}
.dtable tr.uk td{color:#111;background:#fbebeb}

/* help page */
.wrap{width:100%}
.callout{background:#fffdf9;border-color:#0e6f68}
.callout p{font-size:17px;color:#262626}
.callout b{color:#111;font-weight:700}
.help-grid,.next{background:#d9d5cd;border-color:#d9d5cd}
.help-grid a,.next a{background:#fffdf9;color:#1c1c1c}
.help-grid a:hover,.next a:hover{background:#fff}
.help-grid b,.next b{font-family:'DM Sans',sans-serif;font-size:17px;color:#111}
.help-grid span,.next span{font-size:15px;color:#5c5c5c}
.help-grid .go{font-family:'DM Mono',ui-monospace,Menlo,monospace;color:#0e6f68}
.help-note,.disclaimer,.table-note,.sec-sub{font-size:14px;color:#5c5c5c}
.disclaimer{border-color:#d9d5cd}
.steps > li::before{border-color:#b3262f;color:#b3262f;font-family:'DM Mono',ui-monospace,Menlo,monospace}
.steps > li:not(:last-child)::after{background:#d9d5cd}
.warn{border-left-color:#a85a14}
.faq details{border-color:#d9d5cd}
.faq summary{font-size:17px;color:#111;font-weight:500}
.faq summary::after{color:#b3262f}
.faq p{font-size:17px;color:#3d3d3d}

/* billionaires page */
.fact{background:#0d0d0d}
.small-table{border-color:#d9d5cd;background:#fffdf9;font-size:15px}
.small-table th,.small-table td{color:#262626;border-color:#e6e2da}
.small-table thead th{background:#f0ede7;color:#5c5c5c;font-family:'DM Mono',ui-monospace,Menlo,monospace}
.small-table tbody th{color:#111;font-weight:700}
.small-table .num{font-family:'DM Mono',ui-monospace,Menlo,monospace}
.bar-lbl{color:#5c5c5c;font-family:'DM Mono',ui-monospace,Menlo,monospace}
.chart .bar-lbl{color:#c8c8c8}
.toggle{border-color:#bdb8ae}
.toggle button{color:#3d3d3d;font-family:'DM Mono',ui-monospace,Menlo,monospace;min-height:40px}
.toggle button + button{border-left-color:#bdb8ae}
.toggle button[aria-pressed="true"]{background:#1c1c1c;color:#fff}
.toggle button:hover{color:#111}
.toggle button[aria-pressed="true"]:hover{color:#fff}

@media (max-width:640px){
 .hero,.intro{padding:36px 16px 4px}
 .hero h1,.intro h1,h1{font-size:32px}
 .lede,.intro p{font-size:18px}
 article{padding:24px 16px 16px}
 article p,.article p,.steps p,.prose p,.article li,.prose li,article ul.list li{font-size:17px}
 article h2,.article h2,.prose h2,section > h2,.wrap h2{font-size:23px}
 .dtable tr{border-color:#d9d5cd;background:#fffdf9}
 .dtable td::before{color:#5c5c5c;font-family:'DM Mono',ui-monospace,Menlo,monospace}
}
@media (max-width:519px){.help-grid a:last-child:nth-child(odd){grid-column:1/-1}}
</style>"""

FONT_RE = re.compile(r'https://fonts\.googleapis\.com/css2\?family=DM\+Mono[^"]*')
FONT_NEW = "https://fonts.googleapis.com/css2?family=DM+Mono:ital,wght@0,300;0,400;0,500;1,300&family=DM+Sans:wght@400;500;700&family=Syne:wght@700;800&display=swap"

for f in PAGES:
    p = pathlib.Path(f); s = p.read_text()
    s = re.sub(r'<style id="udw-reading">[\s\S]*?</style>\s*', '', s)
    s = FONT_RE.sub(FONT_NEW, s, 1)
    s = s.replace('<style id="udw-chrome">', CSS + '\n<style id="udw-chrome">', 1)
    s = s.replace('<meta name="theme-color" content="#0a0a0a" />', '<meta name="theme-color" content="#0a0a0a" />', 1)
    p.write_text(s); print("reading theme:", f)
